// One owned input worker per MCP session. JSONL requests are strictly serialized and bounded.
#import "macos-automation.h"
#include <unistd.h>
#include <signal.h>
#include <stdatomic.h>
#include <sys/event.h>
#include <errno.h>
#include <poll.h>
#include <CommonCrypto/CommonDigest.h>

static BOOL frameActive;
static atomic_int stopSignal;
static atomic_int fatalExit;

// Receipt control is transport state, never part of a business/recorded request.
// A worker incarnation is generated by this process; frame counters alone are reusable.
static NSString *executionWorkerId;
static NSMutableDictionary *executionFrame;
static BOOL executionEntered;
static atomic_bool executionAwaitingContinue;
static dispatch_semaphore_t executionContinueAvailable;
static id executionContinueReply;
// Only the reader thread accesses these bytes, including prefetched trailing frames.
static NSMutableData *sessionInputBytes;
static BOOL sessionInputClosed;

static BOOL ReceiptToken(id value) {
    if (![value isKindOfClass:NSString.class] || [value length] != 32) return NO;
    return [value rangeOfCharacterFromSet:[[NSCharacterSet characterSetWithCharactersInString:@"0123456789abcdef"] invertedSet]].location == NSNotFound;
}

static BOOL WriteSessionLine(NSDictionary *value) {
    NSData *encoded = [NSJSONSerialization dataWithJSONObject:value options:NSJSONWritingSortedKeys error:nil];
    if (!encoded) return NO;
    NSMutableData *line = [encoded mutableCopy]; uint8_t newline = '\n'; [line appendBytes:&newline length:1];
    const uint8_t *bytes = line.bytes; NSUInteger sent = 0;
    while (sent < line.length) {
        ssize_t count = write(STDOUT_FILENO, bytes + sent, line.length - sent);
        if (count < 0 && errno == EINTR) continue;
        if (count <= 0) return NO;
        sent += (NSUInteger)count;
    }
    return YES;
}

static NSDictionary *FrameReceipt(NSString *phase) {
    NSMutableDictionary *receipt = [executionFrame mutableCopy];
    receipt[@"phase"] = phase;
    return receipt;
}

// A single consumer owns both request and continue framing. Main-thread handlers never
// read stdin; they wait for the reader to deliver one bounded control frame.
static NSData *ReadSessionLine(NSTimeInterval deadline, NSUInteger maxBytes) {
    if (!sessionInputBytes) sessionInputBytes = [NSMutableData data];
    while (!sessionInputClosed && !atomic_load(&stopSignal) && !atomic_load(&fatalExit)) {
        const uint8_t *bytes = sessionInputBytes.bytes;
        for (NSUInteger index = 0; index < sessionInputBytes.length; index++) {
            if (bytes[index] != '\n') continue;
            if (index > maxBytes) { atomic_store(&fatalExit, 65); sessionInputClosed = YES; break; }
            if (maxBytes == 2048 && index + 1 != sessionInputBytes.length) {
                atomic_store(&fatalExit, 70); sessionInputClosed = YES; break;
            }
            NSData *line = [sessionInputBytes subdataWithRange:NSMakeRange(0, index)];
            [sessionInputBytes replaceBytesInRange:NSMakeRange(0, index + 1) withBytes:NULL length:0];
            return line;
        }
        if (sessionInputBytes.length > maxBytes) { atomic_store(&fatalExit, 65); break; }
        if (sessionInputClosed || (deadline && NSProcessInfo.processInfo.systemUptime >= deadline)) break;
        struct pollfd input = {.fd = STDIN_FILENO, .events = POLLIN};
        int ready = poll(&input, 1, 25);
        if (ready < 0 && errno == EINTR) continue;
        if (ready < 0 || (ready > 0 && (input.revents & (POLLERR | POLLNVAL)))) { atomic_store(&fatalExit, 70); break; }
        if (!ready) continue;
        uint8_t buffer[4096]; ssize_t count = read(STDIN_FILENO, buffer, sizeof(buffer));
        if (count < 0 && errno == EINTR) continue;
        if (count < 0) { atomic_store(&fatalExit, 70); break; }
        if (count == 0) {
            if (sessionInputBytes.length) atomic_store(&fatalExit, 70);
            break; // clean EOF only at a complete frame boundary
        }
        [sessionInputBytes appendBytes:buffer length:(NSUInteger)count];
    }
    sessionInputClosed = YES;
    return nil;
}

BOOL RuyiAutomationEnterExecutionReceipt(void) {
    if (!executionFrame) return YES; // original one-terminal-line protocol
    if (executionEntered) return NO;
    executionEntered = YES;
    // Generated only at actual body entry. A precomposed continue cannot acknowledge it.
    executionFrame[@"challenge"] = [[NSUUID.UUID.UUIDString lowercaseString] stringByReplacingOccurrencesOfString:@"-" withString:@""];
    executionContinueReply = nil;
    executionContinueAvailable = dispatch_semaphore_create(0);
    atomic_store(&executionAwaitingContinue, true);
    if (!WriteSessionLine(@{@"id":executionFrame[@"frame_id"], @"receipt":FrameReceipt(@"handler_entered")})) {
        atomic_store(&fatalExit, 70); return NO;
    }
    NSTimeInterval deadline = NSProcessInfo.processInfo.systemUptime + 2.;
    BOOL received = NO;
    while (NSProcessInfo.processInfo.systemUptime < deadline && !atomic_load(&stopSignal) && !atomic_load(&fatalExit)) {
        if (dispatch_semaphore_wait(executionContinueAvailable, dispatch_time(DISPATCH_TIME_NOW, 25 * NSEC_PER_MSEC)) == 0) { received = YES; break; }
    }
    BOOL committed = received && !atomic_load(&stopSignal) && !atomic_load(&fatalExit) && !RuyiAutomationEventsStopping()
        && [executionContinueReply isKindOfClass:NSDictionary.class] && [executionContinueReply count] == 2
        && [executionContinueReply[@"id"] isKindOfClass:NSNumber.class]
        && CFGetTypeID((__bridge CFTypeRef)executionContinueReply[@"id"]) != CFBooleanGetTypeID()
        && [executionContinueReply[@"id"] isEqual:executionFrame[@"frame_id"]]
        && [executionContinueReply[@"receipt"] isKindOfClass:NSDictionary.class]
        && [executionContinueReply[@"receipt"][@"schema"] isKindOfClass:NSNumber.class]
        && CFGetTypeID((__bridge CFTypeRef)executionContinueReply[@"receipt"][@"schema"]) != CFBooleanGetTypeID()
        && [executionContinueReply[@"receipt"][@"frame_id"] isKindOfClass:NSNumber.class]
        && CFGetTypeID((__bridge CFTypeRef)executionContinueReply[@"receipt"][@"frame_id"]) != CFBooleanGetTypeID()
        && [executionContinueReply[@"receipt"] isEqual:FrameReceipt(@"continue")];
    atomic_store(&executionAwaitingContinue, false);
    if (!committed) { atomic_store(&fatalExit, 70); RuyiAutomationStopEvents(); }
    return committed;
}

static int SessionExitCode(int fallback) {
    int failure = atomic_load(&fatalExit);
    return failure ?: fallback;
}

static void HandleFrame(NSData *data) {
    id request = [NSJSONSerialization JSONObjectWithData:data options:0 error:nil];
    NSNumber *identifier = [request isKindOfClass:NSDictionary.class] ? request[@"id"] : nil;
    BOOL valid = [identifier isKindOfClass:NSNumber.class]
        && CFGetTypeID((__bridge CFTypeRef)identifier) != CFBooleanGetTypeID()
        && [identifier doubleValue] >= 1 && [identifier doubleValue] <= 9007199254740991.0
        && [identifier doubleValue] == trunc([identifier doubleValue])
        && [request[@"version"] isKindOfClass:NSNumber.class]
        && CFGetTypeID((__bridge CFTypeRef)request[@"version"]) != CFBooleanGetTypeID()
        && [request[@"version"] isEqual:@1] && [request[@"op"] isKindOfClass:NSString.class];
    BOOL unexpectedContinue = [request isKindOfClass:NSDictionary.class] && request[@"receipt"] != nil;
    if (unexpectedContinue) { valid = NO; atomic_store(&fatalExit, 70); }
    NSDictionary *control = valid ? request[@"_ruyi_receipt"] : nil;
    if (control) {
        valid = [control isKindOfClass:NSDictionary.class] && [control count] == 4
            && [control[@"schema"] isKindOfClass:NSNumber.class]
            && CFGetTypeID((__bridge CFTypeRef)control[@"schema"]) != CFBooleanGetTypeID()
            && [control[@"schema"] isEqual:@1] && ReceiptToken(control[@"invocation_id"])
            && ReceiptToken(control[@"operation_id"]) && [control[@"worker_id"] isEqual:executionWorkerId];
    }
    if (control && !valid) atomic_store(&fatalExit, 70);
    unsigned char digest[CC_SHA256_DIGEST_LENGTH]; CC_SHA256(data.bytes, (CC_LONG)data.length, digest);
    NSMutableString *frameHash = [NSMutableString stringWithCapacity:64];
    for (NSUInteger index = 0; index < sizeof(digest); index++) [frameHash appendFormat:@"%02x", digest[index]];
    dispatch_semaphore_t finished = dispatch_semaphore_create(0);
    BOOL generic = control && valid && [@[@"capture", @"status", @"ocr.image", @"ocr.languages"] containsObject:request[@"op"]];
    // A run-loop block permits bounded AppKit waits to service asynchronous
    // LaunchServices completions and stop signals on the main dispatch queue.
    CFRunLoopPerformBlock(CFRunLoopGetMain(), kCFRunLoopDefaultMode, ^{
        @autoreleasepool {
            frameActive = YES;
            executionFrame = nil; executionEntered = NO;
            if (control && valid) executionFrame = [@{@"schema":@1, @"invocation_id":control[@"invocation_id"],
                @"operation_id":control[@"operation_id"], @"worker_id":executionWorkerId,
                @"worker_pid":@(getpid()), @"frame_id":identifier, @"frame_sha256":frameHash, @"op":request[@"op"]} mutableCopy];
            // Capture this frame, never whichever frame is current when an async
            // OCR/capture callback eventually arrives. Only the main run loop
            // reads completion state or publishes/resets receipt globals.
            NSDictionary *ownedFrame = executionFrame;
            __block BOOL completed = NO;
            void (^finish)(NSDictionary *) = ^(NSDictionary *result) {
                void (^publish)(void) = ^{
                    if (completed) return;
                    if (!frameActive || executionFrame != ownedFrame) { RuyiAutomationStopEvents(); _exit(70); }
                    completed = YES;
                    NSMutableDictionary *response = [result mutableCopy]; response[@"id"] = identifier ?: @0;
                    if (ownedFrame) response[@"receipt"] = FrameReceipt(@"terminal");
                    BOOL wrote = WriteSessionLine(response);
                    executionFrame = nil; executionEntered = NO;
                    if (!wrote) { RuyiAutomationStopEvents(); _exit(70); }
                    frameActive = NO;
                    dispatch_semaphore_signal(finished);
                    int stoppedBy = atomic_load(&stopSignal);
                    if (stoppedBy || atomic_load(&fatalExit)) {
                        RuyiAutomationStopEvents();
                        exit(SessionExitCode(128 + stoppedBy));
                    }
                };
                if (NSThread.isMainThread) publish();
                else {
                    CFRunLoopPerformBlock(CFRunLoopGetMain(), kCFRunLoopDefaultMode, publish);
                    CFRunLoopWakeUp(CFRunLoopGetMain());
                }
            };
            if (valid && [request[@"op"] isEqual:@"session.features"] && !control && [request count] == 3) {
                finish(@{@"ok":@YES, @"protocolVersion":@1, @"executionReceiptVersion":@1,
                    @"worker_id":executionWorkerId, @"worker_pid":@(getpid()),
                    @"executionReceiptOperations":@[@"capture", @"status", @"ocr.image", @"ocr.languages"]});
            } else if (valid) {
                NSMutableDictionary *payload = [request mutableCopy];
                [payload removeObjectsForKeys:@[@"id", @"_ruyi_receipt"]];
                if (generic) {
                    if (!RuyiAutomationEnterExecutionReceipt()) {
                        NSMutableDictionary *failure = [RuyiAutomationFailure(@"execution_receipt_failed", @"Execution receipt was not committed") mutableCopy];
                        failure[@"acted"] = @NO; failure[@"action_sent"] = @NO; failure[@"outcome"] = @"not_dispatched";
                        finish(failure);
                    } else RuyiAutomationRequest([payload copy], finish);
                } else finish(RuyiAutomationInputRequest(payload));
            } else finish(RuyiAutomationFailure(@"invalid_args", @"Invalid native session request envelope"));
        }
    });
    CFRunLoopWakeUp(CFRunLoopGetMain());
    // This deadline belongs to this frame, including a blocked AX call or output consumer.
    // It is not a timer left behind in the persistent worker's run loop.
    BOOL ocr = generic && [request[@"op"] hasPrefix:@"ocr."];
    NSTimeInterval frameDeadline = NSProcessInfo.processInfo.systemUptime + (ocr ? 60. : 12.);
    BOOL completed = NO;
    while (NSProcessInfo.processInfo.systemUptime < frameDeadline) {
        if (dispatch_semaphore_wait(finished, dispatch_time(DISPATCH_TIME_NOW, 5 * NSEC_PER_MSEC)) == 0) { completed = YES; break; }
        if (atomic_exchange(&executionAwaitingContinue, false)) {
            NSData *continuation = ReadSessionLine(MIN(frameDeadline, NSProcessInfo.processInfo.systemUptime + 2.), 2048);
            executionContinueReply = continuation ? [NSJSONSerialization JSONObjectWithData:continuation options:0 error:nil] : nil;
            dispatch_semaphore_signal(executionContinueAvailable);
        }
    }
    if (!completed) {
        RuyiAutomationStopEvents();
        dispatch_group_t cleanup = dispatch_group_create();
        dispatch_group_async(cleanup, dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
            NSTimeInterval deadline = NSProcessInfo.processInfo.systemUptime + 0.45;
            while ([RuyiAutomationRestorePendingClipboard() isEqual:@"pending"] && NSProcessInfo.processInfo.systemUptime < deadline)
                [NSThread sleepForTimeInterval:0.01];
        });
        dispatch_group_wait(cleanup, dispatch_time(DISPATCH_TIME_NOW, NSEC_PER_SEC / 2));
        _exit(70);
    }
}

int RuyiAutomationRunInputSession(void) {
    signal(SIGPIPE, SIG_IGN);
    executionWorkerId = [[NSUUID.UUID.UUIDString lowercaseString] stringByReplacingOccurrencesOfString:@"-" withString:@""];
    // Fail before accepting any frame if independent EOF observation is unavailable.
    // Leaving a stopped but live worker would poison the Python session cache.
#ifdef RUYI_AUTOMATION_TESTING
    NSString *monitorFault = NSProcessInfo.processInfo.environment[@"RUYI_TEST_SESSION_MONITOR_FAILURE"];
    if ([monitorFault isEqual:@"create"]) return 70;
#endif
    int queue = kqueue();
    if (queue < 0) return 70;
    struct kevent change;
    EV_SET(&change, STDIN_FILENO, EVFILT_READ, EV_ADD | EV_CLEAR, 0, 0, NULL);
    int registered;
    do { registered = kevent(queue, &change, 1, NULL, 0, NULL); } while (registered < 0 && errno == EINTR);
#ifdef RUYI_AUTOMATION_TESTING
    if ([monitorFault isEqual:@"register"]) registered = -1;
#endif
    if (registered < 0) { close(queue); return 70; }
    [NSApplication sharedApplication];
    [NSApp setActivationPolicy:NSApplicationActivationPolicyProhibited];
    NSMutableArray *signals = [NSMutableArray array];
    for (NSNumber *value in @[@(SIGTERM), @(SIGINT)]) {
        int number = value.intValue; signal(number, SIG_IGN);
        dispatch_source_t observer = dispatch_source_create(DISPATCH_SOURCE_TYPE_SIGNAL, number, 0, dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0));
        dispatch_source_set_event_handler(observer, ^{
            // An AX call can block the main run loop. Owned input must be released independently.
            RuyiAutomationStopEvents();
            atomic_store(&stopSignal, number);
            dispatch_async(dispatch_get_main_queue(), ^{
                RuyiAutomationEndRecording(@"input_cancelled");
                if (!frameActive) { RuyiAutomationRestorePendingClipboard(); RuyiAutomationResetInputBindings(); exit(SessionExitCode(128 + number)); }
            });
        });
        dispatch_resume(observer); [signals addObject:observer];
    }
    [NSTimer scheduledTimerWithTimeInterval:1 repeats:YES block:^(NSTimer *timer) {
        (void)timer; RuyiAutomationRefreshInputBindings(); RuyiAutomationRefreshRecording();
    }];
    [NSWorkspace.sharedWorkspace.notificationCenter addObserverForName:NSWorkspaceSessionDidResignActiveNotification
        object:nil queue:NSOperationQueue.mainQueue usingBlock:^(NSNotification *note) {
            (void)note; RuyiAutomationEndRecording(@"session_locked");
            RuyiAutomationReleaseEvents(); RuyiAutomationResetInputBindings();
        }];
    // Observe pipe closure independently of the serialized frame reader, which can be waiting on
    // an active gesture or blocked AX call. Do not consume bytes or reorder the protocol responses.
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        struct kevent event;
        while (YES) {
            int result;
#ifdef RUYI_AUTOMATION_TESTING
            if ([monitorFault isEqual:@"wait"]) { errno = EBADF; result = -1; }
            else
#endif
            result = kevent(queue, NULL, 0, &event, 1, NULL);
            if (result < 0 && errno == EINTR) continue;
            if (result <= 0 || (event.flags & EV_ERROR)) {
                atomic_store(&fatalExit, 70);
                RuyiAutomationStopEvents();
                dispatch_async(dispatch_get_main_queue(), ^{
                    RuyiAutomationEndRecording(@"session_closed");
                    RuyiAutomationRestorePendingClipboard(); RuyiAutomationResetInputBindings(); exit(70);
                });
                // The main thread may be blocked in AX. The per-frame watchdog normally
                // exits first; retain a bound even if no frame can finish.
                dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 13 * NSEC_PER_SEC),
                    dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{ _exit(70); });
                break;
            }
            if (event.flags & EV_EOF) {
                RuyiAutomationStopEvents(); break;
            }
        }
        close(queue);
    });
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        NSData *line;
        while ((line = ReadSessionLine(0, 65536)) != nil) {
            if (line.length) HandleFrame(line);
        }
        RuyiAutomationStopEvents();
        dispatch_async(dispatch_get_main_queue(), ^{ RuyiAutomationEndRecording(@"session_closed"); RuyiAutomationResetInputBindings(); exit(SessionExitCode(0)); });
    });
    [NSApp run];
    (void)signals;
    RuyiAutomationStopEvents();
    return SessionExitCode(0);
}
